var app=angular.module("app");app.factory("linksService",function($http){var promise=$http.get("data/links.min.json").then(function(response){return response.data.links});return{getLinks:function(){return promise}}});app.controller("linksCtrl",function($scope,linksService){linksService.getLinks().then(function(links){$scope.linksData=links})});